function knapsack(weights, values, W) {
  const n = weights.length;
  // dp[i][w] = max value using first i items with capacity w
  const dp = Array.from({ length: n + 1 }, () => new Array(W + 1).fill(0));

  for (let i = 1; i <= n; i++) {
    for (let w = 0; w <= W; w++) {
      if (weights[i - 1] <= w) {
        // Choice: include item i-1 OR skip it
        dp[i][w] = Math.max(
          dp[i - 1][w],
          dp[i - 1][w - weights[i - 1]] + values[i - 1]
        );
      } else {
        dp[i][w] = dp[i - 1][w]; // too heavy, must skip
      }
    }
  }
  return dp[n][W];
}

// Space-optimized 1D version:
function knapsack1D(weights, values, W) {
  const dp = new Array(W + 1).fill(0);
  for (let i = 0; i < weights.length; i++) {
    for (let w = W; w >= weights[i]; w--) {
      dp[w] = Math.max(dp[w], dp[w - weights[i]] + values[i]);
    }
  }
  return dp[W];
}

function coinChange(coins, amount) {
  const dp = new Array(amount + 1).fill(amount + 1);
  dp[0] = 0; // zero coins needed for amount 0

  for (let i = 1; i <= amount; i++) {
    for (const coin of coins) {
      if (coin <= i) {
        dp[i] = Math.min(dp[i], dp[i - coin] + 1);
      }
    }
  }
  return dp[amount] > amount ? -1 : dp[amount];
}

// Alternative: BFS approach (often faster in practice)
function coinChangeBFS(coins, amount) {
  const queue = [0];
  const visited = new Set([0]);
  let steps = 0;

  while (queue.length) {
    const size = queue.length;
    for (let s = 0; s < size; s++) {
      const current = queue.shift();
      if (current === amount) return steps;
      for (const coin of coins) {
        const next = current + coin;
        if (next <= amount && !visited.has(next)) {
          visited.add(next);
          queue.push(next);
        }
      }
    }
    steps++;
  }
  return -1;
}

function numSquares(n) {
  const dp = new Array(n + 1).fill(Infinity);
  dp[0] = 0;

  // Precompute squares up to sqrt(n)
  const squares = [];
  for (let i = 1; i * i <= n; i++) {
    squares.push(i * i);
  }

  for (let i = 1; i <= n; i++) {
    for (const sq of squares) {
      if (sq > i) break;
      dp[i] = Math.min(dp[i], dp[i - sq] + 1);
    }
  }
  return dp[n];
}

