function lengthOfLIS(nums) {
  const n = nums.length;
  const dp = new Array(n).fill(1); // dp[i] = LIS ending at i
  let maxLen = 1;

  for (let i = 1; i < n; i++) {
    for (let j = 0; j < i; j++) {
      if (nums[j] < nums[i]) {
        dp[i] = Math.max(dp[i], dp[j] + 1);
      }
    }
    maxLen = Math.max(maxLen, dp[i]);
  }
  return maxLen;
}

// With actual sequence reconstruction:
function getLIS(nums) {
  const n = nums.length;
  const dp = new Array(n).fill(1);
  const prev = new Array(n).fill(-1); // track predecessor
  let maxIdx = 0;

  for (let i = 1; i < n; i++) {
    for (let j = 0; j < i; j++) {
      if (nums[j] < nums[i] && dp[j] + 1 > dp[i]) {
        dp[i] = dp[j] + 1;
        prev[i] = j;
      }
    }
    if (dp[i] > dp[maxIdx]) maxIdx = i;
  }

  // Reconstruct sequence
  const lis = [];
  while (maxIdx !== -1) {
    lis.unshift(nums[maxIdx]);
    maxIdx = prev[maxIdx];
  }
  return lis;
}

function lengthOfLISBinarySearch(nums) {
  const tails = []; // tails[i] = smallest tail of all increasing subsequences of length i+1

  for (const num of nums) {
    let left = 0;
    let right = tails.length;

    // Binary search: find first element >= num
    while (left < right) {
      const mid = Math.floor((left + right) / 2);
      if (tails[mid] < num) {
        left = mid + 1;
      } else {
        right = mid;
      }
    }

    if (left === tails.length) {
      tails.push(num); // num extends longest subsequence
    } else {
      tails[left] = num; // replace to allow smaller numbers
    }
  }
  return tails.length;
}

