function longestPalindrome(s) {
  if (s.length <= 1) return s;

  let start = 0;
  let maxLen = 1;

  function expand(left, right) {
    while (left >= 0 && right < s.length && s[left] === s[right]) {
      const len = right - left + 1;
      if (len > maxLen) {
        maxLen = len;
        start = left;
      }
      left--;
      right++;
    }
  }

  for (let i = 0; i < s.length; i++) {
    expand(i, i);     // odd length: 'aba'
    expand(i, i + 1); // even length: 'abba'
  }

  return s.slice(start, start + maxLen);
}

// DP table approach (O(n^2) time, O(n^2) space):
function longestPalindromeDP(s) {
  const n = s.length;
  const dp = Array.from({ length: n }, () => new Array(n).fill(false));
  let start = 0;
  let maxLen = 1;

  // Every single character is a palindrome
  for (let i = 0; i < n; i++) dp[i][i] = true;

  // Check substrings of length 2
  for (let i = 0; i < n - 1; i++) {
    if (s[i] === s[i + 1]) {
      dp[i][i + 1] = true;
      start = i;
      maxLen = 2;
    }
  }

  // Check lengths 3 to n
  for (let len = 3; len <= n; len++) {
    for (let i = 0; i <= n - len; i++) {
      const j = i + len - 1;
      if (s[i] === s[j] && dp[i + 1][j - 1]) {
        dp[i][j] = true;
        start = i;
        maxLen = len;
      }
    }
  }
  return s.slice(start, start + maxLen);
}

function longestPalindromeSubseq(s) {
  const n = s.length;
  const dp = Array.from({ length: n }, () => new Array(n).fill(0));

  // Base case: single characters are palindromes of length 1
  for (let i = 0; i < n; i++) dp[i][i] = 1;

  // Fill from shorter to longer substrings
  for (let i = n - 2; i >= 0; i--) {
    for (let j = i + 1; j < n; j++) {
      if (s[i] === s[j]) {
        dp[i][j] = dp[i + 1][j - 1] + 2;
      } else {
        dp[i][j] = Math.max(dp[i + 1][j], dp[i][j - 1]);
      }
    }
  }
  return dp[0][n - 1];
}

// Space-optimized to O(n):
function LPS1D(s) {
  const n = s.length;
  let prev = new Array(n).fill(0);

  for (let i = n - 1; i >= 0; i--) {
    const curr = new Array(n).fill(0);
    curr[i] = 1;
    for (let j = i + 1; j < n; j++) {
      if (s[i] === s[j]) {
        curr[j] = prev[j - 1] + 2;
      } else {
        curr[j] = Math.max(prev[j], curr[j - 1]);
      }
    }
    prev = curr;
  }
  return prev[n - 1];
}

function uniquePaths(m, n) {
  const dp = Array.from({ length: m }, () => new Array(n).fill(0));

  // First row and first column: only one way (all right or all down)
  for (let i = 0; i < m; i++) dp[i][0] = 1;
  for (let j = 0; j < n; j++) dp[0][j] = 1;

  // Each cell = paths from above + paths from left
  for (let i = 1; i < m; i++) {
    for (let j = 1; j < n; j++) {
      dp[i][j] = dp[i - 1][j] + dp[i][j - 1];
    }
  }
  return dp[m - 1][n - 1];
}

// Mathematical shortcut (combinatorics):
function uniquePathsComb(m, n) {
  const steps = m + n - 2;
  const down = m - 1;

  // C(steps, down) = steps! / (down! * (steps-down)!)
  let result = 1;
  for (let i = 1; i <= down; i++) {
    result = result * (steps - down + i) / i;
  }
  return result;
}

function minPathSum(grid) {
  const m = grid.length;
  const n = grid[0].length;
  const dp = Array.from({ length: m }, () => new Array(n).fill(0));

  dp[0][0] = grid[0][0];

  // First row: can only come from left
  for (let j = 1; j < n; j++) {
    dp[0][j] = dp[0][j - 1] + grid[0][j];
  }

  // First column: can only come from above
  for (let i = 1; i < m; i++) {
    dp[i][0] = dp[i - 1][0] + grid[i][0];
  }

  // Rest: min of top or left + current cell
  for (let i = 1; i < m; i++) {
    for (let j = 1; j < n; j++) {
      dp[i][j] = Math.min(dp[i - 1][j], dp[i][j - 1]) + grid[i][j];
    }
  }
  return dp[m - 1][n - 1];
}

// Space-optimized O(n):
function minPathSum1D(grid) {
  const n = grid[0].length;
  const dp = new Array(n).fill(0);

  for (let i = 0; i < grid.length; i++) {
    for (let j = 0; j < n; j++) {
      if (i === 0 && j === 0) {
        dp[j] = grid[0][0];
      } else if (i === 0) {
        dp[j] = dp[j - 1] + grid[i][j];
      } else if (j === 0) {
        dp[j] = dp[j] + grid[i][j];
      } else {
        dp[j] = Math.min(dp[j - 1], dp[j]) + grid[i][j];
      }
    }
  }
  return dp[n - 1];
}

function rob(root) {
  // Returns [withRoot, withoutRoot] for each subtree
  function dfs(node) {
    if (!node) return [0, 0];

    const [leftWith, leftWithout] = dfs(node.left);
    const [rightWith, rightWithout] = dfs(node.right);

    // If we rob this node, we cannot rob children
    const withRoot = node.val + leftWithout + rightWithout;
    // If we skip this node, take max of robbing or skipping each child
    const withoutRoot = Math.max(leftWith, leftWithout) + Math.max(rightWith, rightWithout);

    return [withRoot, withoutRoot];
  }

  const [withRoot, withoutRoot] = dfs(root);
  return Math.max(withRoot, withoutRoot);
}

// Post-order traversal: children computed before parent
// State definition:
//   withRoot  = max value if we rob this node
//   withoutRoot = max value if we skip this node

function maxPathSum(root) {
  let maxSum = -Infinity;

  function maxGain(node) {
    if (!node) return 0;

    // Max gain from left and right (ignore negative paths)
    const leftGain = Math.max(maxGain(node.left), 0);
    const rightGain = Math.max(maxGain(node.right), 0);

    // Path through current node: left + node + right
    const priceNewPath = node.val + leftGain + rightGain;
    maxSum = Math.max(maxSum, priceNewPath);

    // Return max gain for parent (can only choose one side)
    return node.val + Math.max(leftGain, rightGain);
  }

  maxGain(root);
  return maxSum;
}

